-- Adds diagnostic and consult services, and demo prices for them at the V3 demo clinics.
-- MRI and CT scans are only offered by the larger hospitals.

alter table clinic_services drop constraint clinic_services_service_check;
alter table clinic_services add constraint clinic_services_service_check check (service in (
    'EXAM', 'CONSULT', 'VACCINATION', 'BLOOD_WORK', 'XRAY', 'ULTRASOUND', 'CT_SCAN', 'MRI',
    'DENTAL', 'SPAY_NEUTER', 'EMERGENCY'));

